	}()
	t.Cleanup(func() {
		testServer.Close()
	})

	port, err := strconv.Atoi(testServer.Port())
	require.NoError(t, err)

	p := MySQLPinger{}
	ctx, cancel := context.WithTimeout(context.Background(), time.Second*30)
	defer cancel()
	err = p.Ping(ctx, PingParams{
		Host:         "localhost",
		Port:         port,
		Username:     "someuser",
		DatabaseName: "somedb",
	})

	require.NoError(t, err)
}
